<?php
namespace App\Domain\Marketing\Services; use App\Domain\Commerce\Enums\PaymentStatus; use App\Domain\Commerce\Models\Order; use App\Domain\Marketing\Models\AnalyticsEvent; use Illuminate\Http\Request; use Illuminate\Support\Str;
class AnalyticsService {public function record(Request $r,string $name,array $payload=[]):?AnalyticsEvent{if(!$r->session()->get('consent.analytics',false))return null;return AnalyticsEvent::create(['event_id'=>(string)Str::uuid(),'event_name'=>$name,'session_hash'=>hash('sha256',$r->session()->getId()),'payload'=>$payload,'occurred_at'=>now()]);} public function recordVerifiedPurchase(Order $o):?AnalyticsEvent{if($o->payment_status!==PaymentStatus::Paid||!$o->analytics_consent)return null;$key='purchase:'.$o->id;if(AnalyticsEvent::where('event_name','purchase')->where('order_id',$o->id)->exists())return null;return AnalyticsEvent::create(['event_id'=>(string)Str::uuid(),'event_name'=>'purchase','order_id'=>$o->id,'payload'=>['order_number'=>$o->order_number,'currency'=>$o->currency,'value_minor'=>$o->total_amount],'occurred_at'=>now()]);}}
